<template><div class="page"><div class="page-header"><h2>报警规则</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="rule_id" label="规则编号" width="100"/><el-table-column prop="rule_name" label="规则名称" min-width="140"/><el-table-column prop="data_type" label="监控类型" width="90"/><el-table-column label="条件" width="70"><template #default="{row}">{{ row.condition_type||'-' }}</template></el-table-column><el-table-column label="下限" width="80"><template #default="{row}">{{ row.threshold_min||'-' }}</template></el-table-column><el-table-column label="上限" width="80"><template #default="{row}">{{ row.threshold_max||'-' }}</template></el-table-column><el-table-column label="严重度" width="80"><template #default="{row}"><el-tag :type="severityTag(row.severity)" size="small">{{ row.severity||'WARNING' }}</el-tag></template></el-table-column><el-table-column label="通知方式" width="80"><template #default="{row}">{{ row.notify_method||'-' }}</template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'规则 — '+(detail?.rule_name||'')" v-model="drawer" width="450px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="规则编号">{{ detail.rule_id }}</el-descriptions-item><el-descriptions-item label="规则名称">{{ detail.rule_name }}</el-descriptions-item><el-descriptions-item label="监控类型">{{ detail.data_type }}</el-descriptions-item><el-descriptions-item label="条件">{{ detail.condition_type||'-' }}</el-descriptions-item><el-descriptions-item label="下限">{{ detail.threshold_min||'-' }}</el-descriptions-item><el-descriptions-item label="上限">{{ detail.threshold_max||'-' }}</el-descriptions-item><el-descriptions-item label="严重度"><el-tag :type="severityTag(detail.severity)" size="small">{{ detail.severity||'WARNING' }}</el-tag></el-descriptions-item><el-descriptions-item label="通知方式">{{ detail.notify_method||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchAlertRules} from '@/api/iot';import type {IotRecord} from '@/api/iot'
const{items,loading,page,perPage,total}=useListPage<IotRecord>(fetchAlertRules);const{drawer,detail,open}=useDetailDrawer<IotRecord>()
function severityTag(s:string){const m:Record<string,string>={INFO:'info',WARNING:'warning',CRITICAL:'danger'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
